// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(ctx context.Context, request HealthRequestObject) (HealthResponseObject, error)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(ctx context.Context, request ReadyRequestObject) (ReadyResponseObject, error)
	// 取得本地维护屏障
	// (POST /v1/barriers)
	AcquireBarrier(ctx context.Context, request AcquireBarrierRequestObject) (AcquireBarrierResponseObject, error)
	// 释放已授权维护屏障
	// (POST /v1/barriers/{barrierId}:release)
	ReleaseBarrier(ctx context.Context, request ReleaseBarrierRequestObject) (ReleaseBarrierResponseObject, error)
	// 接受QA精选翻译命令
	// (POST /v1/cache-answer-translations)
	TranslateCachedAnswer(ctx context.Context, request TranslateCachedAnswerRequestObject) (TranslateCachedAnswerResponseObject, error)
	// 读取已完成的自动缓存翻译
	// (GET /v1/cache-answer-translations/{translationId})
	ReadCacheAnswerTranslation(ctx context.Context, request ReadCacheAnswerTranslationRequestObject) (ReadCacheAnswerTranslationResponseObject, error)
	// 管理术语列表
	// (GET /v1/glossary)
	ListGlossary(ctx context.Context, request ListGlossaryRequestObject) (ListGlossaryResponseObject, error)
	// 整批撤销自动术语
	// (POST /v1/glossary-batches/{batchId}:rollback)
	RollbackAutomaticGlossaryBatch(ctx context.Context, request RollbackAutomaticGlossaryBatchRequestObject) (RollbackAutomaticGlossaryBatchResponseObject, error)
	// 删除术语规则
	// (DELETE /v1/glossary/{termId})
	DeleteGlossaryTerm(ctx context.Context, request DeleteGlossaryTermRequestObject) (DeleteGlossaryTermResponseObject, error)
	// 人工维护术语
	// (PUT /v1/glossary/{termId})
	PutGlossaryTerm(ctx context.Context, request PutGlossaryTermRequestObject) (PutGlossaryTermResponseObject, error)
	// 应用memory已批准提议
	// (POST /v1/glossary:apply-approved-proposal)
	ApplyApprovedGlossaryProposal(ctx context.Context, request ApplyApprovedGlossaryProposalRequestObject) (ApplyApprovedGlossaryProposalResponseObject, error)
	// 读取运行界面字典
	// (GET /v1/interface-strings/{language})
	ReadInterfaceCatalog(ctx context.Context, request ReadInterfaceCatalogRequestObject) (ReadInterfaceCatalogResponseObject, error)
	// 人工编辑界面文本
	// (PUT /v1/interface-strings/{language}/{key})
	PutInterfaceString(ctx context.Context, request PutInterfaceStringRequestObject) (PutInterfaceStringResponseObject, error)
	// 补译界面字符串缺项
	// (POST /v1/interface-strings/{language}:translate)
	RequestInterfaceTranslation(ctx context.Context, request RequestInterfaceTranslationRequestObject) (RequestInterfaceTranslationResponseObject, error)
	// 保存访客显式语言偏好
	// (PUT /v1/language-preferences)
	SaveLanguagePreference(ctx context.Context, request SaveLanguagePreferenceRequestObject) (SaveLanguagePreferenceResponseObject, error)
	// 供网关核对当前语言建议批准
	// (GET /v1/language-suggestion-approvals/{approvalId})
	ReadLanguageSuggestionApproval(ctx context.Context, request ReadLanguageSuggestionApprovalRequestObject) (ReadLanguageSuggestionApprovalResponseObject, error)
	// 读取管理员语言建议付费开关
	// (GET /v1/language-suggestion-policy)
	ReadLanguageSuggestionPolicy(ctx context.Context, request ReadLanguageSuggestionPolicyRequestObject) (ReadLanguageSuggestionPolicyResponseObject, error)
	// 管理员明确启停语言建议付费许可
	// (PUT /v1/language-suggestion-policy)
	PutLanguageSuggestionPolicy(ctx context.Context, request PutLanguageSuggestionPolicyRequestObject) (PutLanguageSuggestionPolicyResponseObject, error)
	// 给访客语言建议
	// (POST /v1/language-suggestions)
	SuggestLanguage(ctx context.Context, request SuggestLanguageRequestObject) (SuggestLanguageResponseObject, error)
	// 读取语言列表
	// (GET /v1/languages)
	ListLanguages(ctx context.Context, request ListLanguagesRequestObject) (ListLanguagesResponseObject, error)
	// 更新语言启用配置
	// (PUT /v1/languages/{tag})
	PutLanguage(ctx context.Context, request PutLanguageRequestObject) (PutLanguageResponseObject, error)
	// 启停公开语言
	// (POST /v1/languages/{tag}/enabled)
	SetLanguageEnabled(ctx context.Context, request SetLanguageEnabledRequestObject) (SetLanguageEnabledResponseObject, error)
	// 批准估价并启用语言翻译
	// (POST /v1/languages/{tag}:approve-plan)
	ApproveLanguagePlan(ctx context.Context, request ApproveLanguagePlanRequestObject) (ApproveLanguagePlanResponseObject, error)
	// 估算启用语言翻译费用
	// (POST /v1/languages/{tag}:estimate)
	EstimateLanguagePlan(ctx context.Context, request EstimateLanguagePlanRequestObject) (EstimateLanguagePlanResponseObject, error)
	// 受控读取已完成域快照归档
	// (GET /v1/snapshots/{snapshotId}/archive)
	ReadSnapshotArchive(ctx context.Context, request ReadSnapshotArchiveRequestObject) (ReadSnapshotArchiveResponseObject, error)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(ctx context.Context, request DiscardSnapshotRequestObject) (DiscardSnapshotResponseObject, error)
	// 导出安全watermark快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(ctx context.Context, request ExportSnapshotRequestObject) (ExportSnapshotResponseObject, error)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(ctx context.Context, request StageSnapshotRequestObject) (StageSnapshotResponseObject, error)
	// 列出译文标题
	// (GET /v1/translation-titles)
	ListTranslationTitles(ctx context.Context, request ListTranslationTitlesRequestObject) (ListTranslationTitlesResponseObject, error)
	// 申请源修订翻译
	// (POST /v1/translations)
	CreateTranslation(ctx context.Context, request CreateTranslationRequestObject) (CreateTranslationResponseObject, error)
	// 查看翻译进度
	// (GET /v1/translations/progress)
	ListTranslationProgress(ctx context.Context, request ListTranslationProgressRequestObject) (ListTranslationProgressResponseObject, error)
	// 取消翻译子链路
	// (POST /v1/translations/{translationId}/cancel)
	CancelTranslation(ctx context.Context, request CancelTranslationRequestObject) (CancelTranslationResponseObject, error)
	// 对照编辑读取
	// (GET /v1/translations/{translationId}/units)
	ReadTranslationUnits(ctx context.Context, request ReadTranslationUnitsRequestObject) (ReadTranslationUnitsResponseObject, error)
	// 人工编辑并自动保护
	// (PUT /v1/translations/{translationId}/units/{unitId})
	EditTranslationUnit(ctx context.Context, request EditTranslationUnitRequestObject) (EditTranslationUnitResponseObject, error)
	// 显式启停人工保护
	// (POST /v1/translations/{translationId}/units/{unitId}/protection)
	SetUnitProtection(ctx context.Context, request SetUnitProtectionRequestObject) (SetUnitProtectionResponseObject, error)
	// 公开读取当前译文
	// (POST /v1/translations:read)
	ReadTranslation(ctx context.Context, request ReadTranslationRequestObject) (ReadTranslationResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// Health operation middleware
func (sh *strictHandler) Health(w http.ResponseWriter, r *http.Request) {
	var request HealthRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.Health(ctx, request.(HealthRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "Health")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(HealthResponseObject); ok {
		if err := validResponse.VisitHealthResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

